return $input.all().map((item) => {
  const input = item.json;
  const attempt = Number(input.retryAttempt ?? 1);
  if (!Number.isInteger(attempt) || attempt < 1) throw new Error('retryAttempt must be a positive integer');
  const rawStatus = input.statusCode ?? input.httpCode ?? input.error?.statusCode ?? input.error?.httpCode;
  const statusCode = Number(rawStatus);
  const errorCode = String(input.errorCode ?? input.code ?? input.error?.code ?? '').toUpperCase();
  const safeMessage = String(input.errorSummary ?? input.error?.message ?? input.message ?? '').toLowerCase();
  const timeout = ['ETIMEDOUT', 'ESOCKETTIMEDOUT', 'ECONNRESET'].includes(errorCode) || /timed? ?out|timeout/.test(safeMessage);
  const transientStatus = statusCode === 429 || (statusCode >= 500 && statusCode <= 599);
  const retryable = timeout || transientStatus;
  const maxRetries = 3;
  const shouldRetry = retryable && attempt <= maxRetries;
  return { json: {
    ...input,
    statusCode: Number.isFinite(statusCode) ? statusCode : null,
    retryAttempt: attempt,
    nextRetryAttempt: shouldRetry ? attempt + 1 : null,
    retryDelaySeconds: shouldRetry ? 2 ** (attempt - 1) : 0,
    retryable,
    shouldRetry,
    retryExhausted: retryable && attempt > maxRetries,
    retryDecision: shouldRetry ? 'retry' : 'fail'
  } };
});
